sct::core::Image Pixels(int w=120,int h=90){sct::core::Image image;if(!image.Create(w,h))throw std::runtime_error("Fixture allocation");for(int y=0;y<h;++y)for(int x=0;x<w;++x){auto* p=image.Row(y)+x*4;p[0]=static_cast<BYTE>((x*17+y*11)%251);p[1]=static_cast<BYTE>((x*31+y*37)%253);p[2]=static_cast<BYTE>((x*53+y*19)%255);p[3]=255;}return image;}
template<class F>bool Reject(F f){try{f();return false;}catch(const std::exception&){return true;}}
