    core::Annotation mosaic;mosaic.tool=Tool::Mosaic;mosaic.rect={10,10,100,80};mosaic.color=RGB(100,130,160);mosaic.mosaicMode=1;auto first=source,second=source;std::fill(second.pixels.begin(),second.pixels.end(),BYTE{0});services::RenderObject(first,mosaic);services::RenderObject(second,mosaic);bool independent=true;for(int y=10;y<80;++y)independent=independent&&memcmp(first.Row(y)+40,second.Row(y)+40,90*4)==0;check(independent&&memcmp(first.Row(0),source.Row(0),120*4)==0&&first.Row(10)[10*4+3]==255,"privacy mosaic output is independent of covered source RGBA and preserves outside pixels");
