    static void Wait(EditorFrame* p){const auto end=GetTickCount64()+8000;do{p->SendMessage(WM_TIMER,1);services::PumpNativeTestMessages();if(!p->WorkingForBuild())return;Sleep(1);}while(GetTickCount64()<end);throw std::runtime_error("Productivity native timeout");}
