    Reset(p);p->SetSelection({0});p->SendMessage(WM_COMMAND,CopyStyle);p->SetSelection({1});const auto source=p->document_.State().base;const auto text=p->document_.State().objects[1].text;const auto rect=p->document_.State().objects[1].rect;const auto run=p->document_.State().objects[1].textRuns[0].color;p->SendMessage(WM_COMMAND,PasteStyle);Wait(p);check(p->document_.State().objects[1].fontSize==25&&p->document_.State().objects[1].text==text&&EqualRect(&rect,&p->document_.State().objects[1].rect)&&p->document_.State().objects[1].textRuns[0].color==run&&p->document_.State().base==source&&p->document_.UndoCount()==1,"native style paste retains target text/runs/geometry/source in one Undo");p->SendMessage(WM_COMMAND,PasteStyle);Wait(p);check(p->document_.UndoCount()==1,"identical style paste skips Undo");p->SendMessage(WM_COMMAND,Undo);Wait(p);check(p->document_.State().objects[1].fontSize==40,"style Undo restores prior target formatting");auto locked=p->document_.State();locked.objects[1].locked=true;p->document_.Reset(locked);p->Changed();Wait(p);p->SetSelection({1});p->SendMessage(WM_COMMAND,PasteStyle);check(p->document_.State().objects[1].fontSize==40&&!p->document_.UndoCount(),"locked style target rejects atomically without Undo");
    Reset(p);p->SetSelection({0});p->SendMessage(WM_COMMAND,CopyStyle);auto* q=new EditorFrame(p->document_.State(),L"",&w,true);q->cursorApplyAudit_=[](LPCTSTR){};w.pages_.push_back(q);w.ResumePage(q);w.Layout();Wait(q);q->SetSelection({1});q->SendMessage(WM_COMMAND,PasteStyle);Wait(q);check(q->document_.State().objects[1].fontSize==25&&p->document_.State().objects[1].fontSize==40,"style buffer transfers across RAM pages without mutating source page");w.Activate(p);Reset(p);p->SetSelection({2});const auto previous=p->document_.State().objects[2].asset;const CString path=(dir/L"replacement.png").c_str();CString error;services::CaptureService::Save(Pixels(40,80),path,error);p->productivityFormAudit_=[](FormDialog& f){f.Fields()[0].value=L"2";return IDOK;};p->replacementPathAudit_=[&]{return path;};p->SendMessage(WM_COMMAND,ReplacePicture);Wait(p);check(p->document_.State().objects[2].asset->width==40&&p->document_.State().objects[2].rect.left==170&&p->document_.UndoCount()==1,"native replacement loads on worker into same object/layer with one Undo");p->SendMessage(WM_COMMAND,Undo);Wait(p);check(p->document_.State().objects[2].asset==previous,"replacement Undo restores exact original shared asset");p->SetSelection({2});p->productivityFormAudit_=[](FormDialog&){return IDCANCEL;};p->SendMessage(WM_COMMAND,ReplacePicture);check(!p->job_.Busy()&&p->document_.UndoCount()==0,"cancelled replacement does not start worker or commit");
    p->productivityFormAudit_=[](FormDialog& f){f.Fields()[0].value=L"30";f.Fields()[1].value=L"20";return IDOK;};p->SendMessage(WM_COMMAND,PictureAdjust);Wait(p);check(p->document_.State().objects[2].brightness==30&&p->document_.UndoCount()==1&&p->document_.State().objects[2].asset==previous,"native Picture brightness/contrast stays editable with original asset");p->SendMessage(WM_COMMAND,PictureAdjustBypass);Wait(p);check(!p->document_.State().objects[2].pictureAdjust&&p->document_.UndoCount()==2,"bypass is an undoable per-Picture toggle");
