    p->productivityFormAudit_=[&](FormDialog& f){++p->revision_;f.Fields()[0].value=L"0";return IDOK;};p->SendMessage(WM_COMMAND,GridSettings);check(!p->gridVisible_&&!p->gridSnap_,"stale grid modal cannot apply settings after document revision changes");
    Reset(p);p->SendMessage(WM_COMMAND,CloneSource);Mouse(p,WM_LBUTTONDOWN,10,180);check(p->cloneSource_==CPoint(10,180)&&!p->dragging_,"clone source click sets origin without drawing");Mouse(p,WM_LBUTTONDOWN,180,170);Mouse(p,WM_MOUSEMOVE,220,180);Mouse(p,WM_LBUTTONUP,220,180);Wait(p);check(p->document_.State().objects.size()==4&&p->document_.State().objects.back().tool==core::Tool::Picture&&p->document_.UndoCount()==1&&p->selected_<0,"native clone gesture commits one editable patch without automatic handles");p->SendMessage(WM_COMMAND,Undo);Wait(p);check(p->document_.State().objects.size()==3,"clone Undo retains original annotations");
